const SECTIONS = [['Crescendo', 25], ['Crescendo 2', 39], ['Intro', 8], ['Build', 8], ['Drop', 16], ['Break', 8], ['Drop 2', 16]]
const TEMPO = {'Crescendo': 138, 'Crescendo 2': 138, 'Intro': 138, 'Build': 138, 'Drop': 138, 'Break': 138, 'Drop 2': 140}

// section lanes: 1 plays, 0 is silent, values in between fade
const section1 = "<1!25 0!95>"  // Crescendo · 25 bars · 138 BPM · A · Am
const section2 = "<0!25 1!39 0!56>"  // Crescendo 2 · 39 bars · 138 BPM · A · Am F C G
